using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

/// <summary>
/// Hermeticity tests for <see cref="KeyEnvFile.GetEnv"/>: a supplied
/// <see cref="IEnvironmentAccessor"/> must be authoritative — it must never
/// fall through to the real process environment.
/// </summary>
public sealed class KeyEnvFileHermeticityTests
{
    private const string TestKey = "VR_TEST_HERMETICITY_KEY";

    [Fact]
    public void GetEnv_SuppliedAccessorMissingKey_ReturnsNull_WhenProcessHasKey()
    {
        // Set a key in the real process environment.
        Environment.SetEnvironmentVariable(TestKey, "process-value");
        try
        {
            var accessor = new DictionaryEnvironmentAccessor();
            // The accessor lacks the key — it must return null, NOT fall through.
            var result = KeyEnvFile.GetEnv(TestKey, accessor);
            Assert.Null(result);
        }
        finally
        {
            Environment.SetEnvironmentVariable(TestKey, null);
        }
    }

    [Fact]
    public void GetEnv_SuppliedAccessorHasKey_ReturnsAccessorValue()
    {
        // Set a DIFFERENT value in the real process env to prove the accessor wins.
        Environment.SetEnvironmentVariable(TestKey, "process-value");
        try
        {
            var accessor = new DictionaryEnvironmentAccessor();
            accessor[TestKey] = "accessor-value";
            var result = KeyEnvFile.GetEnv(TestKey, accessor);
            Assert.Equal("accessor-value", result);
        }
        finally
        {
            Environment.SetEnvironmentVariable(TestKey, null);
        }
    }

    [Fact]
    public void GetEnv_NullAccessor_ReadsProcessEnv()
    {
        Environment.SetEnvironmentVariable(TestKey, "process-value");
        try
        {
            var result = KeyEnvFile.GetEnv(TestKey, accessor: null);
            Assert.Equal("process-value", result);
        }
        finally
        {
            Environment.SetEnvironmentVariable(TestKey, null);
        }
    }
}

using VisualRelay.App.ViewModels;
using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

/// <summary>
/// Hermeticity and regression tests for the Obsidian bridge settings path.
/// - Hydration must never persist (construction is a no-op on disk).
/// - Genuine property changes must persist only changed keys.
/// - The old leaky pattern (empty accessor + fixture vault root) must not
///   corrupt a seeded .env.
/// - The suite-wide <c>XDG_CONFIG_HOME</c> redirect must be active.
/// </summary>
[Collection("Headless")]
public sealed class ObsidianBridgeHermeticityTests : IDisposable
{
    private readonly string _scratch = Path.Combine(Path.GetTempPath(),
        "vr-hermeticity", Guid.NewGuid().ToString("N"));

    public void Dispose() => TestFileSystem.DeleteDirectoryResilient(_scratch);

    /// <summary>
    /// Create a sandboxed accessor (HOME + XDG_CONFIG_HOME in scratch) and
    /// ensure the config directory exists.
    /// </summary>
    private DictionaryEnvironmentAccessor SandboxedEnv()
    {
        var env = new DictionaryEnvironmentAccessor
        {
            ["HOME"] = Path.Combine(_scratch, "home"),
            ["XDG_CONFIG_HOME"] = Path.Combine(_scratch, "xdg")
        };
        Directory.CreateDirectory(env["HOME"]!);
        return env;
    }

    /// <summary>
    /// Seed a .env file with the given bridge settings so the VM's
    /// LoadObsidianBridgeSettings hydrates from known state.
    /// </summary>
    private string SeedEnvFile(DictionaryEnvironmentAccessor env,
        bool enabled, string vaultRoot, int pollSeconds)
    {
        var path = KeyEnvFile.ResolvePathForCurrentUser(env);
        var dir = Path.GetDirectoryName(path)!;
        Directory.CreateDirectory(dir);
        File.WriteAllText(path,
            $"VR_OBSIDIAN_ENABLED={(enabled ? "true" : "false")}\n" +
            $"VR_OBSIDIAN_VAULT_ROOT={vaultRoot}\n" +
            $"VR_OBSIDIAN_POLL_SECONDS={pollSeconds}\n");
        return path;
    }

    [AvaloniaFact]
    public void ConstructingViewModel_AgainstSeededEnv_LeavesFileByteIdentical()
    {
        var env = SandboxedEnv();
        var envPath = SeedEnvFile(env, enabled: true,
            vaultRoot: "/tmp/custom-vault", pollSeconds: 45);
        var originalBytes = File.ReadAllBytes(envPath);

        // Construction alone must not write anything to disk.
        using (new MainWindowViewModel(environmentAccessor: env))
        {
            // nothing — just construct and dispose
        }

        Assert.True(File.Exists(envPath));
        var afterBytes = File.ReadAllBytes(envPath);
        Assert.Equal(originalBytes, afterBytes);
    }

    [AvaloniaFact]
    public void GenuinePropertyChange_PersistsOnlyChangedKey()
    {
        var env = SandboxedEnv();
        var envPath = SeedEnvFile(env, enabled: true,
            vaultRoot: "/tmp/custom-vault", pollSeconds: 45);

        var vm = new MainWindowViewModel(environmentAccessor: env);
        // Toggle ObsidianEnabled from true → false.
        vm.ObsidianEnabled = false;

        var afterContent = File.ReadAllText(envPath);
        // The enabled key should have changed, but the vault root and poll
        // seconds must still be their original values.
        Assert.Contains("VR_OBSIDIAN_ENABLED=false", afterContent,
            StringComparison.Ordinal);
        Assert.Contains("VR_OBSIDIAN_VAULT_ROOT=/tmp/custom-vault",
            afterContent, StringComparison.Ordinal);
        Assert.Contains("VR_OBSIDIAN_POLL_SECONDS=45", afterContent,
            StringComparison.Ordinal);
    }

    [AvaloniaFact]
    public void Regression_EmptyAccessorWithFixtureVaultRoot_DoesNotCorruptSeededEnv()
    {
        var env = SandboxedEnv();
        var envPath = SeedEnvFile(env, enabled: true,
            vaultRoot: "/tmp/custom-vault", pollSeconds: 60);
        var originalBytes = File.ReadAllBytes(envPath);

        // Simulate the old leaky pattern: empty accessor + fixture vault root.
        // With the hermetic change, an empty accessor can't resolve config dir
        // so the persist is a no-op (InvalidOperationException caught by Save).
        var leakyEnv = new DictionaryEnvironmentAccessor();
        var vm = new MainWindowViewModel(environmentAccessor: leakyEnv)
        {
            ObsidianVaultRoot = "/Users/dev/obsidian-vault"
        };

        // The seeded .env must be untouched.
        Assert.True(File.Exists(envPath));
        var afterBytes = File.ReadAllBytes(envPath);
        Assert.Equal(originalBytes, afterBytes);
    }

    [Fact]
    public void XdgConfigHome_IsRedirectedToTempDir()
    {
        // The [ModuleInitializer] in TestModuleInitializer must have set
        // XDG_CONFIG_HOME to a temp directory before any test runs.
        var xdg = Environment.GetEnvironmentVariable("XDG_CONFIG_HOME");
        Assert.NotNull(xdg);
        Assert.NotEmpty(xdg);

        // Should NOT start with the real home directory.
        var realHome = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        Assert.False(xdg.StartsWith(realHome, StringComparison.OrdinalIgnoreCase));

        // Should contain something temp-ish.
        Assert.Contains(Path.GetTempPath().TrimEnd(Path.DirectorySeparatorChar),
            xdg, StringComparison.OrdinalIgnoreCase);
    }
}

using System.Runtime.InteropServices;
using VisualRelay.Core.Configuration;

namespace VisualRelay.Tests;

/// <summary>
/// Tests for <see cref="SettingsAuditLog"/>: every write to bridge settings
/// must leave a durable, attributable, timestamped record.
/// </summary>
public sealed class SettingsAuditLogTests : IDisposable
{
    private readonly string _scratch = Path.Combine(Path.GetTempPath(),
        "vr-audit-log", Guid.NewGuid().ToString("N"));

    public void Dispose() => TestFileSystem.DeleteDirectoryResilient(_scratch);

    private DictionaryEnvironmentAccessor SandboxedEnv()
    {
        var env = new DictionaryEnvironmentAccessor
        {
            ["HOME"] = Path.Combine(_scratch, "home"),
            ["XDG_CONFIG_HOME"] = Path.Combine(_scratch, "xdg")
        };
        Directory.CreateDirectory(env["HOME"]!);
        return env;
    }

    [Fact]
    public void Append_ChangedObsidianKey_WritesCorrectLine()
    {
        var env = SandboxedEnv();
        var procName = System.Diagnostics.Process.GetCurrentProcess().ProcessName;
        var pid = Environment.ProcessId;

        SettingsAuditLog.Append("VR_OBSIDIAN_ENABLED",
            oldValue: "false", newValue: "true",
            source: "settings-ui", accessor: env);

        // Resolve the expected log path (same dir as .env).
        var logPath = Path.Combine(
            Path.GetDirectoryName(KeyEnvFile.ResolvePathForCurrentUser(env))!,
            "settings-audit.log");
        Assert.True(File.Exists(logPath), "Audit log file must exist after append.");

        var content = File.ReadAllText(logPath).TrimEnd();
        var lines = content.Split('\n', StringSplitOptions.RemoveEmptyEntries);
        Assert.Single(lines);

        var line = lines[0].TrimEnd();
        // Format: {ISO8601-UTC} {key} "{old}" -> "{new}" source={source} pid={pid} proc={proc}
        Assert.Contains("VR_OBSIDIAN_ENABLED", line, StringComparison.Ordinal);
        Assert.Contains("\"false\" -> \"true\"", line, StringComparison.Ordinal);
        Assert.Contains("source=settings-ui", line, StringComparison.Ordinal);
        Assert.Contains($"pid={pid}", line, StringComparison.Ordinal);
        Assert.Contains($"proc={procName}", line, StringComparison.Ordinal);
        // Values must be in clear (not redacted) for Obsidian keys.
        Assert.DoesNotContain("<redacted>", line, StringComparison.Ordinal);
    }

    [Fact]
    public void Append_NoOpSave_WritesNothing()
    {
        var env = SandboxedEnv();

        // Simulate a no-op save where nothing changed — the Save method
        // should not call Append at all. But we test Append directly:
        // if we never call Append, the log file must not exist.
        // We verify by checking that the log is absent after only setting up
        // the env — no Append call means no file.
        var logPath = Path.Combine(
            Path.GetDirectoryName(KeyEnvFile.ResolvePathForCurrentUser(env))!,
            "settings-audit.log");
        Assert.False(File.Exists(logPath),
            "Audit log must not exist when no Append was called.");
    }

    [Fact]
    public void Append_NonObsidianKey_RedactsValue()
    {
        var env = SandboxedEnv();
        var procName = System.Diagnostics.Process.GetCurrentProcess().ProcessName;
        var pid = Environment.ProcessId;

        SettingsAuditLog.Append("HF_TOKEN",
            oldValue: "sk-old-secret", newValue: "sk-new-secret",
            source: "settings-ui", accessor: env);

        var logPath = Path.Combine(
            Path.GetDirectoryName(KeyEnvFile.ResolvePathForCurrentUser(env))!,
            "settings-audit.log");
        Assert.True(File.Exists(logPath));

        var content = File.ReadAllText(logPath).TrimEnd();
        var line = content.Split('\n', StringSplitOptions.RemoveEmptyEntries)[0].TrimEnd();

        // Values must be redacted for non-Obsidian keys.
        Assert.Contains("<redacted>", line, StringComparison.Ordinal);
        Assert.Contains($"pid={pid}", line, StringComparison.Ordinal);
        Assert.Contains($"proc={procName}", line, StringComparison.Ordinal);
    }

    [Fact]
    public void Append_MigrationSource_WritesMigrationLine()
    {
        var env = SandboxedEnv();

        SettingsAuditLog.Append("VR_OBSIDIAN_VAULT_ROOT",
            oldValue: null, newValue: "/tmp/migrated-vault",
            source: "migration", accessor: env);

        var logPath = Path.Combine(
            Path.GetDirectoryName(KeyEnvFile.ResolvePathForCurrentUser(env))!,
            "settings-audit.log");
        Assert.True(File.Exists(logPath));

        var content = File.ReadAllText(logPath).TrimEnd();
        Assert.Contains("source=migration", content, StringComparison.Ordinal);
        // null oldValue renders as (unset).
        Assert.Contains("(unset)", content, StringComparison.Ordinal);
    }

    [Fact]
    public void Append_CreatesFileWithHardenedPermissions()
    {
        if (RuntimeInformation.IsOSPlatform(OSPlatform.Windows))
        {
            return;
        }

        var env = SandboxedEnv();

        SettingsAuditLog.Append("VR_OBSIDIAN_ENABLED",
            oldValue: "false", newValue: "true",
            source: "settings-ui", accessor: env);

        var logPath = Path.Combine(
            Path.GetDirectoryName(KeyEnvFile.ResolvePathForCurrentUser(env))!,
            "settings-audit.log");
        Assert.True(File.Exists(logPath));

        // File must be 0600 (owner read+write only).
        var fileMode = File.GetUnixFileMode(logPath);
        Assert.Equal(
            UnixFileMode.UserRead | UnixFileMode.UserWrite,
            fileMode);

        // Parent directory must be 0700.
        var dirMode = File.GetUnixFileMode(
            Path.GetDirectoryName(logPath)!);
        Assert.Equal(
            UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute,
            dirMode);
    }
}

