/// <summary>
/// Reads an environment variable through <paramref name="accessor"/> when
/// non-null. A supplied accessor is <b>authoritative</b> — its answer is
/// returned directly (even <c>null</c>). Only a <c>null</c> accessor reads
/// the real process environment. This makes injected accessors hermetic:
/// a test that supplies a <see cref="IEnvironmentAccessor"/> can never
/// leak through to the real machine config.
/// </summary>
public static string? GetEnv(string name, IEnvironmentAccessor? accessor = null) =>
    accessor is not null
        ? accessor.GetEnvironmentVariable(name)
        : Environment.GetEnvironmentVariable(name);

