/// <summary>
/// Label attached to settings writes so the audit trail can distinguish
/// user-initiated changes from API pushes, migration, etc.
/// </summary>
internal string BridgeSettingsSource { get; set; } = "settings-ui";

private void PersistBridgeSettings()
{
    if (_isHydrating) return;
    try
    {
        ObsidianBridgeSettings.Save(new ObsidianBridgeConfig(
            ObsidianEnabled, ObsidianVaultRoot, ObsidianPollSeconds),
            EnvironmentAccessor, source: BridgeSettingsSource);
        StatusText = "Obsidian bridge settings saved";
    }
    catch { /* best-effort */ }
}

private void LoadObsidianBridgeSettings()
{
    try
    {
        _isHydrating = true;
        var config = ObsidianBridgeSettings.Load(EnvironmentAccessor);
        ObsidianEnabled = config.Enabled;
        ObsidianVaultRoot = config.VaultRoot;
        ObsidianPollSeconds = config.PollSeconds;
    }
    catch { /* best-effort */ }
    finally { _isHydrating = false; }
}

/// <summary>
/// Writes the bridge settings to the user-level <c>.env</c> file via
/// surgical <see cref="KeyEnvFile.Upsert"/> calls. Only keys whose
/// values differ from the current <c>.env</c> state are written.
/// Each change is recorded in the <see cref="SettingsAuditLog"/>.
/// <see cref="KeyEnvFile.Upsert"/> creates the parent directory with
/// <c>0700</c> and the file with <c>0600</c>.
/// </summary>
public static void Save(ObsidianBridgeConfig settings, IEnvironmentAccessor? accessor = null,
    string source = "settings-ui")
{
    try
    {
        // Read the current .env values so we only upsert changed keys.
        var current = KeyEnvFile.Read(accessor);

        UpsertIfChanged("VR_OBSIDIAN_ENABLED",
            current.GetValueOrDefault("VR_OBSIDIAN_ENABLED"),
            settings.Enabled ? "true" : "false",
            source, accessor);
        UpsertIfChanged("VR_OBSIDIAN_VAULT_ROOT",
            current.GetValueOrDefault("VR_OBSIDIAN_VAULT_ROOT"),
            settings.VaultRoot,
            source, accessor);
        UpsertIfChanged("VR_OBSIDIAN_POLL_SECONDS",
            current.GetValueOrDefault("VR_OBSIDIAN_POLL_SECONDS"),
            settings.PollSeconds.ToString(),
            source, accessor);
    }
    catch (InvalidOperationException)
    {
        // Nowhere to save — bail.
    }
}

private static void UpsertIfChanged(string key, string? currentValue,
    string newValue, string source, IEnvironmentAccessor? accessor)
{
    if (string.Equals(currentValue, newValue, StringComparison.Ordinal))
        return;

    KeyEnvFile.Upsert(key, newValue, accessor);
    SettingsAuditLog.Append(key, currentValue, newValue, source, accessor);
}

