using System.Diagnostics;
using System.Globalization;

namespace VisualRelay.Core.Configuration;

/// <summary>
/// Append-only audit trail for user-config writes. Every change to the
/// Obsidian bridge keys is recorded in <c>settings-audit.log</c> next to
/// the <c>.env</c> file.
///
/// The log format is one line per change:
/// <c>{ISO8601-UTC} {key} "{old}" -&gt; "{new}" source={source} pid={pid} proc={proc}</c>
///
/// - <c>VR_OBSIDIAN_*</c> values are logged in clear.
/// - All other keys have their values redacted (<c>&lt;redacted&gt;</c>)
///   because the same <c>.env</c> holds API keys.
/// - Best-effort: never throws.
/// - Bounded: trims to the last ~256 lines when the file exceeds 64 KB.
/// - Creates the parent directory <c>0700</c> and the file <c>0600</c> on
///   non-Windows (same hardening as <see cref="KeyEnvFile"/>).
/// </summary>
public static class SettingsAuditLog
{
    private const string FileName = "settings-audit.log";
    private const int MaxBytes = 64 * 1024; // 64 KB
    private const int TailLines = 256;
    private static readonly object Lock = new();

    /// <summary>
    /// Appends one audit line recording a key change.
    /// Never throws — failures are silently swallowed.
    /// </summary>
    /// <param name="key">The env key that changed.</param>
    /// <param name="oldValue">Previous value, or null if the key was unset.</param>
    /// <param name="newValue">New value.</param>
    /// <param name="source">Label identifying the writer (e.g. "settings-ui",
    ///   "control-api", "migration").</param>
    /// <param name="accessor">Env accessor for path resolution; null uses the
    ///   real process environment.</param>
    public static void Append(
        string key,
        string? oldValue,
        string newValue,
        string source,
        IEnvironmentAccessor? accessor = null)
    {
        try
        {
            var logPath = ResolveLogPath(accessor);
            var line = FormatLine(key, oldValue, newValue, source);

            lock (Lock)
            {
                EnsureDirAndFile(logPath);
                File.AppendAllText(logPath, line + Environment.NewLine);
                TrimIfNeeded(logPath);
            }
        }
        catch
        {
            // Best-effort: never throw.
        }
    }

    // ── Internals (visible to tests) ──────────────────────────────────────

    internal static string ResolveLogPath(IEnvironmentAccessor? accessor)
    {
        var envPath = KeyEnvFile.ResolvePath(accessor);
        var dir = Path.GetDirectoryName(envPath)!;
        return Path.Combine(dir, FileName);
    }

    internal static string FormatLine(string key, string? oldValue,
        string newValue, string source)
    {
        var displayOld = FormatValue(key, oldValue);
        var displayNew = FormatValue(key, newValue);
        var timestamp = DateTimeOffset.UtcNow.ToString("yyyy-MM-ddTHH:mm:ssZ",
            CultureInfo.InvariantCulture);
        var pid = Environment.ProcessId;
        var proc = Process.GetCurrentProcess().ProcessName;

        return $"{timestamp} {key} \"{displayOld}\" -> \"{displayNew}\" source={source} pid={pid} proc={proc}";
    }

    internal static string FormatValue(string key, string? value)
    {
        if (value is null)
            return "(unset)";

        if (key.StartsWith("VR_OBSIDIAN_", StringComparison.Ordinal))
            return value;

        return "<redacted>";
    }

    private static void EnsureDirAndFile(string logPath)
    {
        var dir = Path.GetDirectoryName(logPath);
        if (dir is not null && !Directory.Exists(dir))
        {
            Directory.CreateDirectory(dir);
            if (!OperatingSystem.IsWindows())
            {
                File.SetUnixFileMode(dir,
                    UnixFileMode.UserRead | UnixFileMode.UserWrite | UnixFileMode.UserExecute);
            }
        }

        if (!File.Exists(logPath))
        {
            File.WriteAllText(logPath, "");
            if (!OperatingSystem.IsWindows())
            {
                File.SetUnixFileMode(logPath,
                    UnixFileMode.UserRead | UnixFileMode.UserWrite);
            }
        }
    }

    private static void TrimIfNeeded(string logPath)
    {
        try
        {
            var info = new FileInfo(logPath);
            if (!info.Exists || info.Length <= MaxBytes)
                return;

            var lines = File.ReadAllLines(logPath);
            if (lines.Length <= TailLines)
                return;

            var tail = lines.Skip(lines.Length - TailLines).ToArray();
            File.WriteAllLines(logPath, tail);
        }
        catch
        {
            // Best-effort: if trimming fails, the file just keeps growing.
        }
    }
}

